// The llms.txt files (https://llmstxt.org) for this docs site, built from the docs collection at build time.
//
// Local Review's site commits copies of llms.txt generated by its app (shared/llms.ts). Hallway has no app yet, so
// these are generated here instead, from the pages themselves in sidebar order, which means they can't go stale or
// link a page that doesn't exist. When the app exists and serves its own /llms.txt (docs/06-agent-interface.md),
// consider switching to Local Review's arrangement.
import { getCollection, type CollectionEntry } from 'astro:content';
import { SIDEBAR } from './sidebar.mjs';
import { SITE_URL, TITLE, TAGLINE } from './site.mjs';

type Entry = CollectionEntry<'docs'>;
interface Section {
	label: string;
	entries: Entry[];
}

/** Docs pages grouped and ordered as in the sidebar. */
export async function sections(): Promise<Section[]> {
	const byId = new Map((await getCollection('docs')).map((e) => [e.id, e]));
	const out: Section[] = [];
	const loose: Entry[] = [];
	for (const item of SIDEBAR) {
		if (item.slug) {
			const e = byId.get(item.slug);
			if (e) loose.push(e);
			continue;
		}
		const entries = (item.items ?? []).map((i: { slug: string }) => byId.get(i.slug)).filter(Boolean) as Entry[];
		out.push({ label: item.label, entries });
	}
	if (loose.length) out.push({ label: 'More', entries: loose });
	return out;
}

export const intro = `# ${TITLE}

> ${TAGLINE}. A small, always-on, local-only service for a developer's own machine: a live dashboard of every local web server (declared, discovered from other tools, or simply found listening), with health, uptime and bookmarks; memorable HTTPS hostnames via Caddy; and native launchd services for the apps that should survive a reboot.

**Status: pre-release.** Hallway is a specification with an implementation starting. Nothing described here is shipped; each feature is marked v0, v1 or v2 (see ${SITE_URL}/roadmap/). The npm package \`hallway\` is a placeholder until the first release.

Every page below is also available as Markdown at the same URL with \`.md\` instead of the trailing slash.
`;

/** `/introduction/` → `https://…/introduction.md` */
export const mdUrl = (e: Entry) => `${SITE_URL}/${e.id}.md`;
